b"def parse_size(size_str):
    if 'MB' in size_str:
        return int(size_str.replace(' MB', '')) * 1024 * 1024
    elif 'KB' in size_str:
        return int(size_str.replace(' KB', '')) * 1024
    elif 'B' in size_str:
        return int(size_str.replace(' B', ''))
    else:
        raise ValueError('Invalid size format')"
